pub const MAX_EXACT_INTEGER: i16

🔬This is a nightly-only experimental API. (float_exact_integer_constants #152466)

Maximum integer that can be represented exactly in an f16 value, with no other integer converting to the same floating point value.

For an integer x which satisfies MIN_EXACT_INTEGER <= x <= MAX_EXACT_INTEGER, there is a “one-to-one” mapping between i16 and f16 values. MAX_EXACT_INTEGER + 1 also converts losslessly to f16 and back to i16, but MAX_EXACT_INTEGER + 2 converts to the same f16 value (and back to MAX_EXACT_INTEGER + 1 as an integer) so there is not a “one-to-one” mapping.

    #![feature(f16)]
    #![feature(float_exact_integer_constants)]
    let max_exact_int = f16::MAX_EXACT_INTEGER;
    assert_eq!(max_exact_int, max_exact_int as f16 as i16);
    assert_eq!(max_exact_int + 1, (max_exact_int + 1) as f16 as i16);
    assert_ne!(max_exact_int + 2, (max_exact_int + 2) as f16 as i16);

    // Beyond `f16::MAX_EXACT_INTEGER`, multiple integers can map to one float value
    assert_eq!((max_exact_int + 1) as f16, (max_exact_int + 2) as f16);

