    assert_ne!(max_exact_int + 2, (max_exact_int + 2) as f32 as i32);

    // Beyond `f32::MAX_EXACT_INTEGER`, multiple integers can map to one float value
    assert_eq!((max_exact_int + 1) as f32, (max_exact_int + 2) as f32);

