    assert_ne!(max_exact_int + 2, (max_exact_int + 2) as f64 as i64);

    // Beyond `f64::MAX_EXACT_INTEGER`, multiple integers can map to one float value
    assert_eq!((max_exact_int + 1) as f64, (max_exact_int + 2) as f64);

