pub fn format_into(self, buf: &mut NumBuffer<u32>) -> &str

Allows users to write an integer (in unsigned decimal format) into a variable buf of type NumBuffer that is passed by the caller by mutable reference.

§Examples

    use core::fmt::NumBuffer;

    let n = 0u32;
    let mut buf = NumBuffer::new();
    assert_eq!(n.format_into(&mut buf), "0");

    let n1 = 32u32;
    assert_eq!(n1.format_into(&mut buf), "32");

    let n2 = u32 :: MAX;
    assert_eq!(n2.format_into(&mut buf), u32 :: MAX.to_string());

