pub const fn unbounded_shl(self, rhs: u32) -> u64

Unbounded shift left. Computes self << rhs, without bounding the value of rhs.

If rhs is larger or equal to the number of bits in self, the entire value is shifted out, and 0 is returned.

§Examples

    assert_eq!(0x1_u64.unbounded_shl(4), 0x10);
    assert_eq!(0x1_u64.unbounded_shl(129), 0);
    assert_eq!(0b101_u64.unbounded_shl(0), 0b101);
    assert_eq!(0b101_u64.unbounded_shl(1), 0b1010);
    assert_eq!(0b101_u64.unbounded_shl(2), 0b10100);
    assert_eq!(42_u64.unbounded_shl(64), 0);
    assert_eq!(42_u64.unbounded_shl(1).unbounded_shl(63), 0);

    let start : u64 = 13;
    let mut running = start;
    for i in 0..160 {
        // The unbounded shift left by i is the same as `<< 1` i times
        assert_eq!(running, start.unbounded_shl(i));
        // Which is not always the case for a wrapping shift
        assert_eq!(running == start.wrapping_shl(i), i < 64);

        running <<= 1;
    }

