pub fn upgrade(&self) -> Option<Rc<T, A>>

where A: AllocatorClone,

Attempts to upgrade the Weak pointer to an Rc, delaying dropping of the inner value if successful.

Returns None in the following cases:

• The inner value has since been dropped or moved out.

• This Weak does not point to an allocation.

• The owning reference this Weak is associated with is either not fully-constructed or does not allow an upgrade.

§Examples

    use std::rc::Rc;

    let five = Rc::new(5);

    let weak_five = Rc::downgrade(&five);

    let strong_five: Option<Rc<_>> = weak_five.upgrade();
    assert!(strong_five.is_some());

    // Destroy all strong pointers.
    drop(strong_five);
    drop(five);

    assert!(weak_five.upgrade().is_none());

