pub fn spawn_scoped<'scope, 'env, F, T>( self, scope: &'scope Scope<'scope, 'env>, f: F, ) -> Result<ScopedJoinHandle<'scope, T>>

where F: FnOnce() -> T + Send + 'scope, T: Send + 'scope,

